const s = $json;

const prefix = (s.ui_prefix ?? '').trim();

// Labels
const periodLabel = ({ today:'Dziś', tomorrow:'Jutro', weekend:'Weekend', week:'Tydzień' }[s.period] ?? '—');

const themeLabel = ({
  all: 'Wszystkie', teatr: 'Teatr', film: 'Film', koncert: 'Koncert',
  spotkanie: 'Spotkanie', warsztat: 'Warsztat', wystawa: 'Wystawa',
  wycieczka: 'Wycieczka', sport: 'Sport', inne: 'Inne',
}[s.theme] ?? '—');

const payLabel = ({
  all: 'Wszystkie', free: 'Bezpłatne', paid: 'Płatne', unknown: 'Nieznane',
}[s.pay] ?? '—');

const lr = Number(s.lr ?? 0);
const lrLabel = (lr === 1) ? 'Tak' : 'Nie';

const hint = s.period
  ? 'Możesz zmienić ustawienia lub zacząć od nowa.'
  : 'Najpierw wybierz okres.';

// Text (prefix optional)
const ui_text = [
  prefix || null,
  'Ustawienia:',
  `• Okres: ${periodLabel}`,
  `• Kategoria: ${themeLabel}`,
  `• Płatność: ${payLabel}`,
  `• Długoterminowe: ${lrLabel}`,
  '',
  hint
].filter(Boolean).join('\n');

// LR toggle
const lrButton = (lr === 1)
  ? { text: 'Ukryj długoterminowe', callback_data: 'v2|set|lr=0' }
  : { text: 'Pokaż długoterminowe', callback_data: 'v2|set|lr=1' };

// Keyboard (conditional search)
const keyboard = [
  [{ text: 'Wybór okresu', callback_data: 'v2|menu|period' }],
  [
    { text: 'Wybór kategorii', callback_data: 'v2|menu|theme' },
    { text: 'Wybór płatności', callback_data: 'v2|menu|pay' },
  ],
  [lrButton],
];

if (s.period) keyboard.push([{ text: 'Pokaż wyniki', callback_data: 'v2|run|search' }]);

keyboard.push([{ text: 'Zacznij od nowa', callback_data: 'v2|nav|reset' }]);

const reply_markup = { inline_keyboard: keyboard };

return [{ json: { ...s, ui_text, reply_markup } }];
